back-face-culling.pseudocode:
def is_back_face(v0, v1, v2, eye):
    # 정점이 반시계 순서 → 외적이 바깥쪽 법선
    n = cross(sub(v1, v0), sub(v2, v0))
    view = sub(v0, eye)  # 시점 → 다각형 시선 벡터
    return dot(n, view) >= 0  # 0 이상이면 뒷면(측면 포함)

def cull(polygons, eye):
    visible = []
    for poly in polygons:
        v0, v1, v2 = poly[0], poly[1], poly[2]
        if not is_back_face(v0, v1, v2, eye):
            visible.append(poly)  # 앞면만 다음 단계로
    return visible

back-substitution.pseudocode:
def back_substitution(A, b):
    # A: n×n 상삼각행렬 (대각 성분 ≠ 0)
    n = len(b)
    x = [0.0] * n
    for i in range(n - 1, -1, -1):  # 마지막 행부터 역순
        s = b[i]
        for j in range(i + 1, n):
            s -= A[i][j] * x[j]  # 이미 구한 해 대입
        x[i] = s / A[i][i]
    return x  # 연산량 O(n²)

