backward-pass.pseudocode:
def backward_pass(order, dur, succ, ef):
    # order: 위상 정렬 순서, ef: 전진 계산의 EF
    project_end = max(ef.values())
    lf, ls = {}, {}
    for a in reversed(order):  # 종료 → 시작 방향
        if succ[a]:
            lf[a] = min(ls[s] for s in succ[a])
        else:
            lf[a] = project_end  # 종료 활동
        ls[a] = lf[a] - dur[a]
    return lf, ls

def total_float(ls, es):
    # 총여유 TF = LS - ES, TF = 0이면 주공정
    return {a: ls[a] - es[a] for a in ls}

