base-case.pseudocode:
def factorial(n):
    if n < 0:
        raise ValueError  # 입력 검증
    if n <= 1:  # 기저 조건: 직접 반환
        return 1
    return n * factorial(n - 1)  # 기저 쪽으로 축소

def fib(n):
    if n == 0:  # 기저 조건 1
        return 0
    if n == 1:  # 기저 조건 2
        return 1
    return fib(n - 1) + fib(n - 2)

basic-encoding-rules.pseudocode:
def ber_length(n):
    if n < 128:
        return [n]  # 단형식: 1바이트
    body = []
    while n:
        body.insert(0, n & 0xFF)
        n >>= 8
    return [0x80 | len(body)] + body  # 장형식

def ber_tlv(tag, value):
    # tag: 1바이트 태그, value: 바이트 리스트
    return [tag] + ber_length(len(value)) + value

# 예: INTEGER 5 → [0x02, 0x01, 0x05]
# SEQUENCE { INTEGER 5 } → [0x30, 0x03, 0x02, 0x01, 0x05]

bayesian-filter.pseudocode:
def train(spam_docs, ham_docs):
    count = {'spam': {}, 'ham': {}}
    for label, docs in (('spam', spam_docs),
                        ('ham', ham_docs)):
        for doc in docs:
            for w in set(doc):  # 단어가 등장한 문서 수
                c = count[label]
                c[w] = c.get(w, 0) + 1
    return count, len(spam_docs), len(ham_docs)

def spam_prob(words, model):
    count, ns, nh = model
    log_s = log(ns / (ns + nh))  # 사전확률 P(스팸)
    log_h = log(nh / (ns + nh))
    for w in set(words):
        # 라플라스 평활로 0 확률 방지
        ps = (count['spam'].get(w, 0) + 1) / (ns + 2)
        ph = (count['ham'].get(w, 0) + 1) / (nh + 2)
        log_s += log(ps)
        log_h += log(ph)
    return 1 / (1 + exp(log_h - log_s))  # P(스팸 | 단어)
